    print(f"  Difference: {ord(encoded[i]) - ord('flag{'[i])}")
    print(f"  XOR: {ord(encoded[i]) ^ ord('flag{'[i])}")

# Try a simple ROT (Caesar cipher) and see if we get a pattern
for rot in range(1, 27):
